import {
  encodeDeployData,
  encodeFunctionData,
  getAddress,
  getContractAddress,
  keccak256,
  parseAbi,
  stringToHex,
  type Address,
  type Hex,
} from "viem";

export const SINGLETON_FACTORY_ADDRESS = getAddress(
  "0xce0042B868300000d44A59004Da54A005ffdcf9f",
);
export const SINGLETON_FACTORY_CODE_HASH =
  "0xc4d5542b53a8b779595a20a8ddd60e58a6c49d3c3decc2df83ced1c69c8ca807";
export const SINGLETON_FACTORY_RUNTIME_CODE =
  "" as Hex;
export const STANDING_ORDER_BATCH_EXECUTOR_SALT = keccak256(
  stringToHex("pull-pool-keeper/StandingOrderBatchExecutor/v1"),
);
export const STANDING_ORDER_BATCH_DEPLOY_GAS_LIMIT = 650_000n;

export const singletonFactoryAbi = parseAbi([
  "function deploy(bytes initCode, bytes32 salt) returns (address payable createdContract)",
]);

export const standingOrderBatchExecutorAbi = parseAbi([
  "constructor(address owner)",
  "function MAX_ORDERS() view returns (uint256)",
  "function owner() view returns (address)",
  "function execute((address order,uint256 builderBidBps)[] orders,uint256 minimumOwnerReturn) returns (uint256 succeeded,uint256 grossReward,uint256 builderPayment)",
  "event BatchExecuted(uint256 attempted,uint256 succeeded,uint256 grossReward,uint256 builderPayment,uint256 ownerReturn)",
  "error EmptyBatch()",
  "error InvalidOwner()",
  "error OwnerReturnBelowMinimum(uint256 actual,uint256 minimum)",
  "error PaymentFailed()",
  "error ReentrantCall()",
  "error TooManyOrders()",
  "error Unauthorized()",
  "error UnexpectedBalance()",
]);

export interface StandingOrderBatchMember {
  readonly order: Address;
  readonly crankFee: bigint;
  readonly builderBidBps: bigint;
}

// Generated from solc 0.8.28, Cancun, optimizer enabled with 1,000,000 runs.
export const STANDING_ORDER_BATCH_EXECUTOR_BYTECODE =
  "" as Hex;
const STANDING_ORDER_BATCH_EXECUTOR_RUNTIME_TEMPLATE =
  "" as Hex;
const OWNER_IMMUTABLE_OFFSETS = [82, 277, 1251] as const;

function patchOwnerImmutable(template: Hex, owner: Address): Hex {
  const ownerWord = owner.slice(2).padStart(64, "0");
  let body = template.slice(2);
  for (const offset of OWNER_IMMUTABLE_OFFSETS) {
    const start = offset * 2;
    body = `${body.slice(0, start)}${ownerWord}${body.slice(start + 64)}`;
  }
  return `0x${body}`;
}

export function standingOrderBatchExecutorDeployment(owner: Address): {
  readonly initCode: Hex;
  readonly address: Address;
  readonly expectedRuntimeCode: Hex;
  readonly expectedRuntimeCodeHash: Hex;
  readonly deployData: Hex;
} {
  const canonicalOwner = getAddress(owner);
  const initCode = encodeDeployData({
    abi: standingOrderBatchExecutorAbi,
    bytecode: STANDING_ORDER_BATCH_EXECUTOR_BYTECODE,
    args: [canonicalOwner],
  });
  const address = getContractAddress({
    from: SINGLETON_FACTORY_ADDRESS,
    opcode: "CREATE2",
    salt: STANDING_ORDER_BATCH_EXECUTOR_SALT,
    bytecode: initCode,
  });
  const expectedRuntimeCode = patchOwnerImmutable(
    STANDING_ORDER_BATCH_EXECUTOR_RUNTIME_TEMPLATE,
    canonicalOwner,
  );
  return {
    initCode,
    address,
    expectedRuntimeCode,
    expectedRuntimeCodeHash: keccak256(expectedRuntimeCode),
    deployData: encodeFunctionData({
      abi: singletonFactoryAbi,
      functionName: "deploy",
      args: [initCode, STANDING_ORDER_BATCH_EXECUTOR_SALT],
    }),
  };
}

export function standingOrderBatchEconomics(
  members: readonly StandingOrderBatchMember[],
): {
  readonly grossReward: bigint;
  readonly builderPayment: bigint;
  readonly ownerReturn: bigint;
} {
  if (members.length === 0 || members.length > 64) {
    throw new Error("standing-order batch must contain 1 to 64 orders");
  }
  let grossReward = 0n;
  let builderPayment = 0n;
  const seen = new Set<string>();
  for (const member of members) {
    if (member.crankFee <= 0n || member.builderBidBps < 0n) {
      throw new Error("standing-order batch members require positive fees and nonnegative bids");
    }
    const key = member.order.toLowerCase();
    if (seen.has(key)) {
      throw new Error(`duplicate standing order ${member.order}`);
    }
    seen.add(key);
    grossReward += member.crankFee;
    builderPayment +=
      (member.crankFee * member.builderBidBps) / 10_000n;
  }
  return {
    grossReward,
    builderPayment,
    ownerReturn:
      builderPayment > grossReward
        ? 0n
        : grossReward - builderPayment,
  };
}

export function encodeStandingOrderBatchExecution(
  members: readonly StandingOrderBatchMember[],
  minimumOwnerReturn: bigint,
): Hex {
  if (minimumOwnerReturn <= 0n) {
    throw new Error("minimum owner return must be positive");
  }
  return encodeFunctionData({
    abi: standingOrderBatchExecutorAbi,
    functionName: "execute",
    args: [
      members.map((member) => ({
        order: member.order,
        builderBidBps: member.builderBidBps,
      })),
      minimumOwnerReturn,
    ],
  });
}
